#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_N 90
static long memo[MAX_N + 1];
static char computed[MAX_N + 1];

static long fib(int n)
{
    if (computed[n])
        return memo[n];
    if (n == 0) {
        memo[0] = 0;
        computed[0] = 1;
        return 0;
    }
    if (n == 1) {
        memo[1] = 1;
        computed[1] = 1;
        return 1;
    }
    long a = fib(n - 1);
    long b = fib(n - 2);
    memo[n] = a + b;
    computed[n] = 1;
    return memo[n];
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("NEGATIVE");
        return 0;
    }
    if (n > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long result = fib((int)n);
    printf("%lld\n", result);
    return 0;
}
